SELECT

FROM tb_payment


    AND id = #{id}


    AND ascription = #{ascription}


    AND name = #{name}


    AND account = #{account}


    AND bank = #{bank}


    AND reason = #{reason}


    AND price_lower = #{priceLower}


    AND price_upper = #{priceUpper}


    AND act_id = #{actId}


    AND create_user = '${createUser}'


    AND user_name = '${userName}'


    AND create_time >= '${startTime}'


    AND create_time <= '${endTime}'


    AND status = '${status}'


ORDER BY create_time ASC
